import {_electron as electron} from 'playwright';import assert from 'node:assert/strict';import {mkdtemp} from 'node:fs/promises';import path from 'node:path';import os from 'node:os';
const data=await mkdtemp(path.join(os.tmpdir(),'nodus-image-ui-')),evidence=await mkdtemp(path.join(process.env.RUNNER_TEMP,'nodus-images-evidence-'));
const app=await electron.launch({executablePath:process.env.NODUS_QA_EXE,args:[`--user-data-dir=${data}/profile`],env:{...process.env,NODUS_DATA_DIR:data}});
try{const page=await app.firstWindow();const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.locator('#imageGenerationButton').click();await page.locator('#imageSettings').waitFor();assert(await page.locator('#imageEndpoint').isVisible());assert.equal(await page.locator('#enableImageGeneration').isChecked(),false);
 await page.locator('#imageModel').fill('test-image-model');await page.locator('#imageApiKey').fill('synthetic-image-key');await page.locator('#imageEndpoint').fill('https://images.example.test/v1');await page.locator('#enableImageGeneration').check();await page.locator('#saveImages').click();await page.locator('#imageConnectionStatus').filter({hasText:'未产生生图费用'}).waitFor();assert.equal(await page.locator('#imageApiKey').inputValue(),'');
 const status=await page.evaluate(()=>window.forma.imageStatus());assert(status.configured&&status.enabled);assert(!JSON.stringify(status).includes('synthetic-image-key'));assert.equal((await page.evaluate(()=>window.forma.bootstrap())).model.configured,false,'image service must not change the text connection');
 await app.evaluate(({BrowserWindow})=>{const w=BrowserWindow.getAllWindows()[0];w.setMinimumSize(640,600);w.setContentSize(720,640);});await page.waitForFunction(()=>innerWidth===720);
 await page.locator('#imageSettings').evaluate(e=>{e.scrollTop=e.scrollHeight;});
 assert(await page.locator('#closeImageSettings').evaluate(e=>{const r=e.getBoundingClientRect(),d=e.closest('dialog').getBoundingClientRect();return r.top>=d.top&&r.bottom<=d.bottom&&document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)?.closest('#closeImageSettings')===e;}),'Close must remain visible and clickable after scrolling');
 assert(await page.locator('#imageSettings').evaluate(e=>e.scrollWidth<=e.clientWidth+1),'No horizontal overflow at narrow width');
 await page.screenshot({path:path.join(evidence,'configured.png')});await page.locator('#closeImageSettings').click();await page.locator('#imageGenerationButton').click();assert.equal(await page.locator('#imageModel').inputValue(),'test-image-model');await page.locator('#imageApiKey').fill('must-clear-on-provider-change');await page.locator('#imageProvider').selectOption('minimax-cn');assert.equal(await page.locator('#imageApiKey').inputValue(),'');assert.equal(await page.locator('#imageEndpoint').inputValue(),'https://api.minimaxi.com/v1');assert.equal(await page.locator('#imageModel').inputValue(),'image-01');await page.locator('#imageSize').selectOption('16:9');await page.locator('#imageApiKey').fill('synthetic-minimax-key');await page.locator('#saveImages').click();await page.locator('#imageConnectionStatus').filter({hasText:'未产生生图费用'}).waitFor();assert.equal((await page.evaluate(()=>window.forma.imageStatus())).provider,'minimax-cn');await page.screenshot({path:path.join(evidence,'minimax.png')});await page.locator('#disconnectImages').click();await page.locator('#imageConnectionStatus').filter({hasText:'已移除'}).waitFor();assert.equal((await page.evaluate(()=>window.forma.imageStatus())).configured,false);assert.deepEqual(errors,[]);await (await import('node:fs/promises')).writeFile(path.join(evidence,'result.json'),JSON.stringify({passed:true,paidCalls:0,evidence,independentConnection:true,explicitEnable:true,secretCleared:true,closeRemainsVisible:true,narrowWidth:720,minimaxPreset:true,providerSwitchClearsKey:true}));
}finally{await app.close();}
